import React from "react";
import { AbsoluteFill, Easing, OffthreadVideo, Sequence, interpolate, interpolateColors, spring, staticFile, useCurrentFrame } from "remotion";
import { loadFont as loadCormorant } from "@remotion/google-fonts/CormorantGaramond";
import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import { LEG } from "./legendas";
import { MAPA } from "./mapa";

// v3 (cliente: "mais ênfase na voz, algo mais animado, ficou um pouco robótica"): voz nova (Roberta, estabilidade 0,
// src/voz-v2-final.wav, 62,8 s). As cenas continuam escritas no tempo da voz v1: o tempo do quadro passa pela tabela MAPA
// (voz nova → voz antiga, palavra por palavra) e os vídeos tocam em velocidade normal a partir do início novo da cena.
// v2 (retorno: textos perto da borda e muito espaçados; mais dinâmica no começo, inversão de cor): coluna de
// 780 px (margem 150), blocos agrupados e centralizados, menos espaço entre letras, abertura em 4 batidas com inversão.
// MALLONE HAIR (cliente Gioger Lucas) · Novembro do Autocuidado: 50% OFF no corte + SPA DETOX de presente.
// Vitrine: os takes do corte (cor tratada e fundo desfocado em tools/tratar_takes.py) em tela cheia com legenda dinâmica,
// intercalados com cenas desenhadas nas falas da oferta (tesoura, relógio, 50%, presente, fios, oferta).
// Identidade: não veio logo; cores do próprio salão (avental caramelo, cabelo preto, parede creme) + dourado. Tom elegante.
// Voz: Roberta (eleven_v3), src/voz-v1-final.wav, 59,6 s, entra em LEAD. Tempos = tempo da palavra na voz final.

export const MH_FPS = 30;
const LEAD = 0.1;
export const MH3_FRAMES = Math.round(63.5 * MH_FPS);
const interp = (x: number, xs: number[], ys: number[]) => {
  if (x <= xs[0]) return ys[0] + (x - xs[0]);
  const n = xs.length - 1;
  if (x >= xs[n]) return ys[n] + (x - xs[n]);
  let i = 0; while (xs[i + 1] < x) i++;
  return ys[i] + (ys[i + 1] - ys[i]) * (x - xs[i]) / (xs[i + 1] - xs[i]);
};
const NOVO = MAPA.map((p) => p[0]), VELHO = MAPA.map((p) => p[1]);
const toOld = (tn: number) => interp(tn, NOVO, VELHO);
const toNew = (to: number) => interp(to, VELHO, NOVO);
// quadro (no vídeo novo) em que acontece um tempo da voz antiga
const fr = (s: number) => Math.round((toNew(s) + LEAD) * MH_FPS);

const { fontFamily: SERIF } = loadCormorant("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SERIF_I } = loadCormorant("italic", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadPoppins("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });

const ESP = "#1B120E";
const CAR = "#B5763F";
const CREAM = "#F4ECE1";
const GOLD = "linear-gradient(180deg, #F6E2AE 0%, #E0B66E 55%, #B9853F 100%)";
const GOLD_S = "#DDB06A";
const SH = "0 6px 30px rgba(0,0,0,0.55), 0 2px 6px rgba(0,0,0,0.5)";

const cl = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const IO = Easing.inOut(Easing.cubic);
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IO });
const sp = (t: number, a: number, damping = 16, stiffness = 130) =>
  t < a ? 0 : spring({ frame: (t - a) * MH_FPS, fps: MH_FPS, config: { damping, stiffness, mass: 0.9 } });
const gold = (): React.CSSProperties => ({ backgroundImage: GOLD, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" });

// texto que sobe da linha (máscara) e fica parado
const Rise: React.FC<{ t: number; at: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ t, at, children, style }) => {
  const e = sp(t, at, 20, 150);
  return (
    <span style={{ display: "inline-block", overflow: "hidden", verticalAlign: "bottom", padding: "0 0.04em 0.12em", margin: "0 -0.04em -0.12em" }}>
      <span style={{ display: "inline-block", transform: `translateY(${((1 - e) * 115).toFixed(2)}%)`, ...style }}>{children}</span>
    </span>
  );
};
// g = dourado: o degradê vai em cada palavra (background-clip não passa para filho com transform)
const Line: React.FC<{ t: number; at: number; text: string; style: React.CSSProperties; step?: number; g?: boolean }> = ({ t, at, text, style, step = 0.07, g }) => (
  <div style={{ display: "flex", justifyContent: "center", gap: "0.24em", whiteSpace: "nowrap", ...style }}>
    {text.split(" ").map((w, i) => <Rise key={i} t={t} at={at + i * step} style={g ? gold() : undefined}>{w}</Rise>)}
  </div>
);
const Pop: React.FC<{ t: number; at: number; children: React.ReactNode; style?: React.CSSProperties; from?: number }> = ({ t, at, children, style, from = 0.4 }) => {
  const e = sp(t, at, 14, 140);
  return <div style={{ opacity: Math.min(1, e * 2.5), transform: `scale(${(from + (1 - from) * e).toFixed(4)})`, ...style }}>{children}</div>;
};

// ───────── vídeo do cliente em tela cheia, câmera andando ─────────
type ClipP = { t: number; a: number; b: number; src: string; trim: number; z: [number, number]; o?: string; dx?: number };
const Clip: React.FC<ClipP> = ({ t, a, b, src, trim, z, o = "50% 45%", dx = 0 }) => {
  const p = interpolate(t, [a - 0.4, b + 0.4], [0, 1], { ...cl, easing: Easing.inOut(Easing.sin) });
  const punch = 1 - sp(t, a - 0.25, 22, 110);
  const s = z[0] + (z[1] - z[0]) * p + 0.07 * punch;
  return (
    <Sequence from={fr(a - 0.4)} durationInFrames={fr(b + 0.4) - fr(a - 0.4)} layout="none">
      <AbsoluteFill style={{ background: ESP, overflow: "hidden" }}>
        <OffthreadVideo muted src={staticFile(`gioger-lucas/${src}.mp4`)} trimBefore={Math.round((trim - 0.4) * MH_FPS)}
          style={{ width: "100%", height: "100%", objectFit: "cover", transformOrigin: o, transform: `translateX(${(dx * (p - 0.5)).toFixed(1)}px) scale(${s.toFixed(4)})` }} />
        <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 820, background: "linear-gradient(0deg, rgba(20,12,8,0.82) 0%, rgba(20,12,8,0.5) 45%, rgba(20,12,8,0) 100%)" }} />
      </AbsoluteFill>
    </Sequence>
  );
};

// vídeo do salão andando atrás das cenas de oferta, sob véu na cor da marca (fundo liso parado lê como parado)
const Fundo: React.FC<{ t: number; a: number; b: number; src: string; trim: number }> = ({ t, a, b, src, trim }) => {
  const p = lin(t, a - 0.4, b + 0.4);
  return (
    <Sequence from={fr(a - 0.4)} durationInFrames={fr(b + 0.4) - fr(a - 0.4)} layout="none">
      <AbsoluteFill style={{ overflow: "hidden" }}>
        <OffthreadVideo muted src={staticFile(`gioger-lucas/${src}.mp4`)} trimBefore={Math.round((trim - 0.4) * MH_FPS)}
          style={{ width: "100%", height: "100%", objectFit: "cover", filter: "blur(8px)", transform: `scale(${(1.18 - 0.1 * p).toFixed(4)}) translateY(${(30 - 60 * p).toFixed(1)}px)` }} />
        <div style={{ position: "absolute", inset: 0, background: "rgba(27,18,14,0.8)" }} />
      </AbsoluteFill>
    </Sequence>
  );
};

// ───────── abertura v2 · quatro batidas com inversão de cor, tesoura e corte ─────────
const Tesoura: React.FC<{ ang: number; size: number }> = ({ ang, size }) => {
  const blade = (sgn: number) => (
    <g transform={`rotate(${sgn * ang})`}>
      <path d={`M 0 0 L ${sgn * 16} -40 L ${sgn * 6} -330 L ${sgn * -2} -330 L ${sgn * -14} -20 Z`} fill="url(#mhG2)" />
      <path d={`M 0 0 L ${sgn * -22} 70`} stroke="url(#mhG2)" strokeWidth={18} strokeLinecap="round" />
      <circle cx={sgn * -40} cy={128} r={52} fill="none" stroke="url(#mhG2)" strokeWidth={16} />
    </g>
  );
  return (
    <svg width={size} height={size * 1.4} viewBox="-200 -360 400 560">
      <defs><linearGradient id="mhG2" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#F6E2AE" /><stop offset="0.55" stopColor="#E0B66E" /><stop offset="1" stopColor="#A9752F" /></linearGradient></defs>
      {blade(1)}{blade(-1)}
      <circle cx={0} cy={0} r={11} fill={ESP} stroke="#F6E2AE" strokeWidth={5} />
    </svg>
  );
};
const CUT = 2.5;
const B1 = -0.1, B2 = 0.55, B3 = 1.15, B4 = 1.75;
// palavra que bate: entra grande e assenta com mola curta, depois fica parada
const Slam: React.FC<{ t: number; at: number; children: React.ReactNode; style: React.CSSProperties }> = ({ t, at, children, style }) => {
  const e = sp(t, at, 15, 170);
  return <div style={{ opacity: Math.min(1, e * 3), transform: `scale(${(1.45 - 0.45 * e).toFixed(4)})`, filter: e < 0.7 ? `blur(${((0.7 - e) * 20).toFixed(1)}px)` : undefined, whiteSpace: "nowrap", ...style }}>{children}</div>;
};
const Batida: React.FC<{ t: number; a: number; bg: string; children: React.ReactNode }> = ({ t, a, bg, children }) => (
  <AbsoluteFill style={{ background: bg, transform: `scale(${(1 + 0.07 * lin(t, a, a + 0.9)).toFixed(4)}) rotate(${(-1.2 + 2.4 * lin(t, a, a + 0.9)).toFixed(2)}deg)` }}>
    <AbsoluteFill style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 28 }}>{children}</AbsoluteFill>
  </AbsoluteFill>
);
const AberturaConteudo: React.FC<{ t: number }> = ({ t }) => {
  const snips = [2.05, CUT - 0.12];
  let ang = 24;
  for (const s of snips) { const c = interpolate(t, [s - 0.16, s, s + 0.2], [24, 2, 24], cl); ang = Math.min(ang, c); }
  if (t > CUT - 0.12) ang = 2;
  const tes = sp(t, B4 - 0.05, 16, 140);
  // inversões: cada batida nasce de dentro da anterior (círculo, diagonal, cortina)
  const p2 = k(t, B2 - 0.12, 0.24), p3 = k(t, B3 - 0.12, 0.24), p4 = k(t, B4 - 0.12, 0.24);
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      {t < B3 + 0.2 ? (
        <Batida t={t} a={B1} bg={CREAM}>
          <Slam t={t} at={B1} style={{ fontFamily: SERIF, fontWeight: 700, fontSize: 262, color: ESP, lineHeight: 0.9, letterSpacing: "0.02em" }}>TODA</Slam>
        </Batida>
      ) : null}
      {t >= B2 - 0.12 && t < B4 + 0.2 ? (
        <AbsoluteFill style={{ clipPath: `circle(${(p2 * 1250).toFixed(0)}px at 540px 960px)` }}>
          <Batida t={t} a={B2} bg={ESP}>
            <Slam t={t} at={B2} style={{ fontFamily: SERIF, fontWeight: 700, fontSize: 150, lineHeight: 1, padding: "0 10px 16px", ...gold() }}>MUDANÇA</Slam>
          </Batida>
        </AbsoluteFill>
      ) : null}
      {t >= B3 - 0.12 ? (
        <AbsoluteFill style={{ clipPath: `polygon(0 0, ${(-60 + p3 * 220).toFixed(1)}% 0, ${(-120 + p3 * 220).toFixed(1)}% 100%, 0 100%)` }}>
          <Batida t={t} a={B3} bg={CAR}>
            <Slam t={t} at={B3} style={{ fontFamily: SANS, fontWeight: 800, fontSize: 150, color: CREAM, lineHeight: 1, letterSpacing: "-0.01em" }}>COMEÇA</Slam>
            <Slam t={t} at={B3 + 0.18} style={{ fontFamily: SANS, fontWeight: 800, fontSize: 150, color: ESP, lineHeight: 1, letterSpacing: "-0.01em" }}>COM</Slam>
          </Batida>
        </AbsoluteFill>
      ) : null}
      {t >= B4 - 0.12 ? (
        <AbsoluteFill style={{ clipPath: `inset(0 ${((1 - p4) * 50).toFixed(2)}% 0 ${((1 - p4) * 50).toFixed(2)}%)` }}>
          <AbsoluteFill style={{ background: ESP }} />
          <Fundo t={t} a={B4} b={CUT + 0.2} src="IMG_0040" trim={0.6} />
          <AbsoluteFill style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 30, transform: `scale(${(1 + 0.06 * lin(t, B4, CUT + 0.5)).toFixed(4)})` }}>
            <div style={{ opacity: Math.min(1, tes * 2.5), transform: `rotate(${(-24 + (1 - tes) * -50).toFixed(2)}deg) scale(${(0.5 + 0.5 * tes).toFixed(3)})` }}><Tesoura ang={ang} size={300} /></div>
            <Line t={t} at={B4 + 0.05} text="uma escolha." style={{ fontFamily: SERIF_I, fontStyle: "italic", fontWeight: 700, fontSize: 150, lineHeight: 1.05 }} g />
          </AbsoluteFill>
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};
const Abertura: React.FC<{ t: number }> = ({ t }) => {
  if (t < CUT) return <AberturaConteudo t={t} />;
  const line = k(t, CUT - 0.06, 0.14);
  const open = interpolate(t, [CUT + 0.1, CUT + 0.55], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
  const A = "polygon(0 0, 100% 0, 100% 40%, 0 60%)";
  const Bp = "polygon(0 60%, 100% 40%, 100% 100%, 0 100%)";
  const d = open * 1250;
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ clipPath: A, transform: `translate(${(-d * 0.19).toFixed(1)}px, ${(-d).toFixed(1)}px)` }}><AberturaConteudo t={t} /></AbsoluteFill>
      <AbsoluteFill style={{ clipPath: Bp, transform: `translate(${(d * 0.19).toFixed(1)}px, ${d.toFixed(1)}px)` }}><AberturaConteudo t={t} /></AbsoluteFill>
      {open < 0.6 ? <div style={{ position: "absolute", left: -100, width: 1280 * line, top: 960 - 3, height: 6, background: GOLD, transform: "rotate(-10.3deg)", transformOrigin: "0 50%", opacity: 1 - open * 1.6, boxShadow: "0 0 24px rgba(240,205,140,0.8)" }} /> : null}
    </AbsoluteFill>
  );
};

// coluna central: blocos agrupados e centralizados no quadro, margem de 150 px
const Coluna: React.FC<{ gap?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ gap = 34, children, style }) => (
  <AbsoluteFill style={{ padding: "0 150px", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap, ...style }}>{children}</AbsoluteFill>
);
// inversão de cor: círculo na cor nova abrindo de um ponto (fica atrás do conteúdo)
const Inverte: React.FC<{ t: number; at: number; color: string; x?: number; y?: number }> = ({ t, at, color, x = 540, y = 960 }) => {
  const p = interpolate(t, [at - 0.1, at + 0.35], [0, 1], { ...cl, easing: IO });
  return p > 0 ? <AbsoluteFill style={{ background: color, clipPath: `circle(${(p * 2300).toFixed(0)}px at ${x}px ${y}px)` }} /> : null;
};
const mixC = (t: number, at: number, a: string, b: string) => interpolateColors(t, [at - 0.05, at + 0.25], [a, b]);

// ───────── cena · "este momento chegou": relógio, e a tela inverte no "chegou" ─────────
const Momento: React.FC<{ t: number }> = ({ t }) => {
  const a = 13.6, CH = 14.42;
  const sweep = sp(t, a + 0.05, 13, 70);
  const inn = sp(t, a - 0.1, 18, 120);
  const ring = lin(t, CH, CH + 0.6);
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      <Inverte t={t} at={CH} color={ESP} y={700} />
      <Coluna gap={40} style={{ transform: `scale(${(1 + 0.06 * lin(t, a, 15.6)).toFixed(4)})` }}>
        <div style={{ position: "relative", width: 500, height: 500, transform: `scale(${(0.7 + 0.3 * inn).toFixed(4)}) rotate(${((1 - inn) * -20).toFixed(2)}deg)` }}>
          {ring > 0 && ring < 1 ? <div style={{ position: "absolute", inset: -10, borderRadius: 270, border: `6px solid ${GOLD_S}`, transform: `scale(${(1 + 0.25 * ring).toFixed(3)})`, opacity: 1 - ring }} /> : null}
          <svg width={500} height={500} viewBox="-300 -300 600 600">
            <circle r={280} fill={mixC(t, CH, "#FFFFFF", "#2A1C15")} stroke={mixC(t, CH, ESP, GOLD_S)} strokeWidth={16} />
            {[...Array(12)].map((_, i) => (
              <line key={i} x1={0} y1={-238} x2={0} y2={i % 3 === 0 ? -200 : -218} stroke={i % 3 === 0 ? CAR : mixC(t, CH, ESP, CREAM)} strokeWidth={i % 3 === 0 ? 12 : 6} strokeLinecap="round" transform={`rotate(${i * 30})`} />
            ))}
            <line x1={0} y1={20} x2={0} y2={-120} stroke={mixC(t, CH, ESP, CREAM)} strokeWidth={18} strokeLinecap="round" transform={`rotate(${-150 + 150 * sweep})`} />
            <line x1={0} y1={30} x2={0} y2={-190} stroke={CAR} strokeWidth={12} strokeLinecap="round" transform={`rotate(${-300 + 300 * sweep})`} />
            <circle r={16} fill={mixC(t, CH, ESP, GOLD_S)} />
          </svg>
        </div>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
          <Line t={t} at={a + 0.02} text="ESTE MOMENTO" style={{ fontFamily: SERIF, fontWeight: 700, fontSize: 96, color: mixC(t, CH, ESP, CREAM), letterSpacing: "0.01em", lineHeight: 1.05 }} />
          <Line t={t} at={CH} text="chegou." style={{ fontFamily: SERIF_I, fontStyle: "italic", fontWeight: 700, fontSize: 170, lineHeight: 1.0 }} g />
        </div>
      </Coluna>
    </AbsoluteFill>
  );
};

// ───────── cena · 50% de desconto no corte, Novembro do Autocuidado ─────────
const Desconto: React.FC<{ t: number }> = ({ t }) => {
  const a = 20.1;
  const n = Math.round(50 * interpolate(t, [20.18, 20.8], [0, 1], { ...cl, easing: Easing.out(Easing.cubic) }));
  const big = sp(t, a, 15, 120);
  const cal = sp(t, 22.5, 13, 110);
  const cam = 1.05 - 0.05 * interpolate(t, [a - 0.3, 25.2], [0, 1], { ...cl, easing: Easing.out(Easing.quad) });
  return (
    <AbsoluteFill style={{ background: ESP }}>
      <Fundo t={t} a={20.1} b={24.95} src="IMG_0047" trim={8.5} />
      <Coluna gap={22} style={{ transform: `scale(${cam.toFixed(4)})` }}>
        <div style={{ display: "flex", alignItems: "flex-start", opacity: Math.min(1, big * 2), transform: `scale(${(0.5 + 0.5 * big).toFixed(4)})`, marginBottom: -30 }}>
          <span style={{ fontFamily: SERIF, fontWeight: 700, fontSize: 330, lineHeight: 0.95, fontVariantNumeric: "tabular-nums", letterSpacing: "-0.02em", padding: "0 8px 24px", ...gold() }}>{n}</span>
          <span style={{ fontFamily: SERIF, fontWeight: 700, fontSize: 180, lineHeight: 1, marginTop: 24, padding: "0 8px 16px", ...gold() }}>%</span>
        </div>
        <Line t={t} at={20.45} text="OFF" style={{ fontFamily: SANS, fontWeight: 800, fontSize: 96, color: CREAM, letterSpacing: "0.12em", paddingLeft: "0.12em", lineHeight: 1 }} />
        <Pop t={t} at={21.3}>
          <div style={{ padding: "16px 52px", borderRadius: 999, background: CAR, fontFamily: SANS, fontWeight: 800, fontSize: 60, color: CREAM, letterSpacing: "0.03em", whiteSpace: "nowrap" }}>NO CORTE</div>
        </Pop>
        {/* folha de calendário: Novembro do Autocuidado */}
        <div style={{ position: "relative", width: 560, height: 420, marginTop: 66, opacity: Math.min(1, cal * 3), transform: `translateY(${((1 - cal) * -420).toFixed(1)}px) rotate(${((1 - cal) * 14).toFixed(2)}deg)`, transformOrigin: "50% 0%" }}>
          <div style={{ position: "absolute", inset: 0, borderRadius: 34, background: CREAM, boxShadow: "0 30px 60px rgba(0,0,0,0.45)", overflow: "hidden" }}>
            <div style={{ height: 124, background: CAR, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: SANS, fontWeight: 800, fontSize: 60, color: CREAM, letterSpacing: "0.06em" }}>NOVEMBRO</div>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", paddingTop: 34 }}>
              <Line t={t} at={23.25} text="do" style={{ fontFamily: SERIF_I, fontStyle: "italic", fontWeight: 600, fontSize: 74, color: CAR, lineHeight: 1 }} />
              <Line t={t} at={23.42} text="Autocuidado" style={{ fontFamily: SERIF_I, fontStyle: "italic", fontWeight: 700, fontSize: 108, color: ESP, lineHeight: 1.1 }} />
            </div>
          </div>
          {[140, 420].map((x) => <div key={x} style={{ position: "absolute", left: x - 15, top: -24, width: 30, height: 60, borderRadius: 15, background: ESP, border: `5px solid ${GOLD_S}` }} />)}
        </div>
      </Coluna>
    </AbsoluteFill>
  );
};

// ───────── cena · quem agendar nesta semana ganha o SPA DETOX (a tela inverte quando a caixa abre) ─────────
const Presente: React.FC<{ t: number }> = ({ t }) => {
  const a = 28.3, OP = 31.18;
  const box = sp(t, a, 15, 110);
  const shake = t > 30.3 && t < 31.15 ? Math.sin((t - 30.3) * 38) * 4 * lin(t, 30.3, 31.1) : 0;
  const lid = sp(t, OP, 12, 120);
  const glow = k(t, OP, 0.4);
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      <Inverte t={t} at={OP} color={ESP} y={930} />
      <Coluna gap={30} style={{ transform: `scale(${(1 + 0.08 * lin(t, a, 32.5)).toFixed(4)})` }}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
          <Line t={t} at={28.9} text="QUEM AGENDAR" style={{ fontFamily: SANS, fontWeight: 800, fontSize: 78, color: mixC(t, OP, ESP, CREAM), letterSpacing: "-0.01em", lineHeight: 1.1 }} />
          <Line t={t} at={29.8} text="nesta semana" style={{ fontFamily: SERIF_I, fontStyle: "italic", fontWeight: 700, fontSize: 112, color: mixC(t, OP, CAR, GOLD_S), lineHeight: 1.05 }} />
        </div>
        {/* caixa de presente */}
        <div style={{ position: "relative", width: 440, height: 400, marginTop: 70, opacity: Math.min(1, box * 3), transform: `translateY(${((1 - box) * 700 + 12 * Math.sin((t - a) * 2.4)).toFixed(1)}px) rotate(${(shake + 1.5 * Math.sin((t - a) * 1.7)).toFixed(2)}deg)`, transformOrigin: "50% 100%" }}>
