const DESTAQUE = new Set(["mudar.", "novo,", "aparência", "espelho", "satisfação.", "momento", "certo", "visual,", "transformar", "condição", "especial",
  "transformação.", "experiência", "agendar", "semana", "capilar", "intensiva", "autocuidado", "você,", "beleza", "nova", "versão.", "Mallone", "Hair,", "Hair."]);
const VIDEO: [number, number][] = [[2.7, 5.55], [5.55, 10.15], [10.15, 13.6], [15.3, 20.1], [24.95, 28.3], [32.2, 33.95], [38.45, 42.05], [42.05, 46.65], [46.65, 49.5]];
const Legenda: React.FC<{ t: number }> = ({ t }) => {
  const win = VIDEO.find(([a, b]) => t >= a && t < b);
  if (!win) return null;
  let cur = -1;
  LEG.forEach(([ws], i) => { const s = ws[0][1] - 0.06; if (s >= win[0] - 0.12 && s < win[1] - 0.25 && t >= s) cur = i; });
