  const [ws, end] = LEG[cur];
  const next = LEG[cur + 1]?.[0][0][1] ?? 99;
  if (t > Math.min(next - 0.06, end + 0.6)) return null;
  const marca = ws.some(([w]) => w.startsWith("Mallone") || w === "Autocuidado,");
  return (
