  );
};

// ───────── montagem ─────────
type Tr = "flood" | "wipeUp" | "wipeDown" | "diag" | "barn" | "zoom" | "blur" | "push" | "none";
type Cena = { a: number; b: number; tr: Tr; at?: [number, number]; el: (t: number) => React.ReactNode };
const CENAS: Cena[] = [
  { a: 2.7, b: 5.55, tr: "none", el: (t) => <Clip t={t} a={2.7} b={5.55} src="IMG_0040" trim={1.6} z={[1.04, 1.14]} o="40% 45%" /> },
  { a: 5.55, b: 10.15, tr: "zoom", el: (t) => <Clip t={t} a={5.55} b={10.15} src="IMG_0035" trim={0.6} z={[1.12, 1.02]} o="35% 50%" dx={40} /> },
  { a: 10.15, b: 13.6, tr: "diag", el: (t) => <Clip t={t} a={10.15} b={13.6} src="IMG_0037" trim={0.5} z={[1.02, 1.12]} o="50% 40%" /> },
  { a: 13.6, b: 15.3, tr: "flood", at: [540, 1500], el: (t) => <Momento t={t} /> },
  { a: 15.3, b: 20.1, tr: "zoom", el: (t) => <Clip t={t} a={15.3} b={20.1} src="IMG_0038" trim={1.5} z={[1.0, 1.08]} o="50% 30%" dx={-30} /> },
  { a: 20.1, b: 24.95, tr: "wipeUp", el: (t) => <Desconto t={t} /> },
  { a: 24.95, b: 28.3, tr: "barn", el: (t) => <Clip t={t} a={24.95} b={28.3} src="IMG_0039" trim={0.5} z={[1.1, 1.0]} o="55% 40%" dx={50} /> },
  { a: 28.3, b: 32.2, tr: "push", el: (t) => <Presente t={t} /> },
  { a: 32.2, b: 33.95, tr: "flood", at: [540, 1000], el: (t) => <Clip t={t} a={32.2} b={33.95} src="IMG_0044" trim={0.5} z={[1.02, 1.1]} o="50% 30%" /> },
  { a: 33.95, b: 38.45, tr: "wipeDown", el: (t) => <Fios t={t} /> },
  { a: 38.45, b: 42.05, tr: "flood", at: [540, 1650], el: (t) => <Clip t={t} a={38.45} b={42.05} src="IMG_0044" trim={3.0} z={[1.0, 1.1]} o="50% 40%" dx={-40} /> },
  { a: 42.05, b: 46.65, tr: "blur", el: (t) => <Clip t={t} a={42.05} b={46.65} src="IMG_0044" trim={9.0} z={[1.1, 1.0]} o="55% 45%" /> },
  { a: 46.65, b: 49.5, tr: "diag", el: (t) => <Clip t={t} a={46.65} b={49.5} src="IMG_0045" trim={0.6} z={[1.0, 1.08]} o="55% 45%" dx={30} /> },
  { a: 49.5, b: 55.9, tr: "flood", at: [540, 1500], el: (t) => <Oferta t={t} /> },
  { a: 55.9, b: 61, tr: "wipeUp", el: (t) => <><Clip t={t} a={55.9} b={61} src="IMG_0047" trim={2.6} z={[1.06, 1.0]} o="45% 40%" /><Fecho t={t} /></> },
];
const entrada = (c: Cena, t: number): React.CSSProperties => {
  const p = interpolate(t, [c.a - 0.28, c.a + 0.14], [0, 1], { ...cl, easing: IO });
  if (p >= 1 || c.tr === "none") return {};
  switch (c.tr) {
    case "flood": { const [x, y] = c.at ?? [540, 960]; return { clipPath: `circle(${(p * 2300).toFixed(0)}px at ${x}px ${y}px)` }; }
    case "wipeUp": return { clipPath: `inset(${((1 - p) * 100).toFixed(2)}% 0 0 0)` };
    case "wipeDown": return { clipPath: `inset(0 0 ${((1 - p) * 100).toFixed(2)}% 0)` };
    case "diag": { const x = -60 + p * 220; return { clipPath: `polygon(0 0, ${x}% 0, ${x - 60}% 100%, 0 100%)` }; }
    case "barn": return { clipPath: `inset(0 ${((1 - p) * 50).toFixed(2)}% 0 ${((1 - p) * 50).toFixed(2)}%)` };
    case "zoom": return { opacity: p, transform: `scale(${(1.25 - 0.25 * p).toFixed(4)})`, filter: `blur(${((1 - p) * 18).toFixed(1)}px)` };
    case "blur": return { opacity: p, filter: `blur(${((1 - p) * 24).toFixed(1)}px)` };
    case "push": return { transform: `translateY(${((1 - p) * 1920).toFixed(1)}px)` };
  }
  return {};
};
const Borda: React.FC<{ c: Cena; t: number }> = ({ c, t }) => {
  // linha dourada fina na frente das cortinas (só onde há borda reta)
  const p = interpolate(t, [c.a - 0.28, c.a + 0.14], [0, 1], { ...cl, easing: IO });
  if (p <= 0 || p >= 1) return null;
  if (c.tr === "wipeUp") return <div style={{ position: "absolute", left: 0, right: 0, top: (1 - p) * 1920 - 3, height: 6, background: GOLD }} />;
  if (c.tr === "wipeDown") return <div style={{ position: "absolute", left: 0, right: 0, top: p * 1920 - 3, height: 6, background: GOLD }} />;
  if (c.tr === "push") return <div style={{ position: "absolute", left: 0, right: 0, top: (1 - p) * 1920 - 3, height: 6, background: GOLD }} />;
  return null;
};

export const MalloneNovembroV3: React.FC = () => {
  const t = toOld(useCurrentFrame() / MH_FPS - LEAD);
  return (
    <AbsoluteFill style={{ background: ESP }}>
      {CENAS.map((c, i) => (t < c.a - 0.3 || t > c.b + 0.35 ? null : (
        <AbsoluteFill key={i} style={entrada(c, t)}>{c.el(t)}</AbsoluteFill>
      )))}
      {CENAS.map((c, i) => <Borda key={`b${i}`} c={c} t={t} />)}
      <Legenda t={t} />
      {t < CUT + 0.6 ? <AbsoluteFill><Abertura t={t} /></AbsoluteFill> : null}
    </AbsoluteFill>
  );
};

